{
  "root_causes": [
    {
      "service": "user",
      "fault_kind": "pod_unavailable",
      "evidence": [
        {"kind": "metric", "sql": "SELECT time, service_name, metric, value FROM abnormal_metrics WHERE service_name='user' AND metric='k8s.deployment.available' ORDER BY time LIMIT 5", "claim": "The user deployment reports 0 available pods for the entire abnormal window, from its first sample onward."},
        {"kind": "metric", "sql": "SELECT 'norm' p, count(*) n, max(time) last_seen FROM normal_metrics WHERE service_name='user' AND attr_k8s_pod_name='user-544b8d4448-dmgn6' UNION ALL SELECT 'abn', count(*), max(time) FROM abnormal_metrics WHERE service_name='user' AND attr_k8s_pod_name='user-544b8d4448-dmgn6'", "claim": "The user pod reports metrics until about 01:55:34 in normal and never appears in the abnormal window."},
        {"kind": "trace", "sql": "SELECT c.service_name, c.span_name, c.attr_status_code, count(*) n, round(quantile_cont(c.duration,0.5)/1e6,3) med_ms FROM abnormal_traces r JOIN abnormal_traces c ON c.trace_id=r.trace_id AND c.parent_span_id=r.span_id WHERE c.span_name='user.User/CheckUser' GROUP BY ALL", "claim": "Every frontend call to user.User/CheckUser in the abnormal window returns Error within about 0.02 ms; no user server spans exist."}
      ]
    },
    {
      "service": "attractions",
      "fault_kind": "container_memory_saturated",
      "evidence": [
        {"kind": "metric", "sql": "SELECT 'norm' p, round(avg(value)/1e6,1) rss_mb FROM normal_metrics WHERE service_name='attractions' AND metric='container.memory.rss' UNION ALL SELECT 'abn', round(avg(value)/1e6,1) FROM abnormal_metrics WHERE service_name='attractions' AND metric='container.memory.rss'", "claim": "Attractions container RSS rises from about 25 MB normal to about 717 MB average abnormal, with CPU near zero."},
        {"kind": "trace", "sql": "SELECT service_name, span_name, attr_span_kind, count(*) n FROM abnormal_traces WHERE service_name='attractions' OR span_name LIKE 'attractions.%' GROUP BY ALL", "claim": "No attractions server spans and no frontend calls to attractions appear in the abnormal window, versus about 521 attractions spans normally."}
      ]
    }
  ],
  "propagation": [
    {
      "from": "user",
      "to": "frontend",
      "evidence": [
        {"kind": "trace", "sql": "SELECT r.span_name root_name, r.attr_http_response_status_code code, count(*) n FROM abnormal_traces r JOIN abnormal_traces c ON c.trace_id=r.trace_id AND c.parent_span_id=r.span_id WHERE r.service_name='frontend' AND r.span_name LIKE 'HTTP %' AND c.span_name='user.User/CheckUser' GROUP BY ALL", "claim": "Frontend HTTP routes that call CheckUser (/cinema, /user, /reservation) return 500 quickly after the user check fails."}
      ]
    },
    {
      "from": "attractions",
      "to": "frontend",
      "evidence": [
        {"kind": "trace", "sql": "SELECT span_name, attr_http_response_status_code code, count(*) n, round(max(duration)/1e6,3) max_ms FROM abnormal_traces WHERE service_name='frontend' AND span_name IN ('HTTP /cinema','HTTP /museums','HTTP /restaurants') GROUP BY ALL", "claim": "Frontend attraction routes (/cinema, /museums, /restaurants) all return 500 in the abnormal window, with no attractions child spans."}
      ]
    }
  ]
}
